"""klein_grammar_coder.py : Klein and Simmons' Computational Grammar Coder (1963), built to the paper.

Source: "A Computational Approach to Grammatical Coding of English Words", J. ACM 10(3):334-347 (your Drive PDF).
What the paper fixes and is used here:
  * 30 word classes (Table 1), spelled as the paper prints them
  * a battery of independent tests whose outputs are multiplied logically (set intersection); a test that knows nothing
    allows NOUN, VERB, ADJ so that nothing valid is zeroed out; incompatible tests give NONE
  * function-word dictionary (under 400 words, unique codes); capitalization test (non-initial capital -> NOUN/ADJ);
    numeral test (-> ADJ); suffix test 1 (plural-type -s/-es/-ies, -ing, -ed, -us -ss -is -as -i -um -ae -a); suffix test 2
    (derivational endings, checked longest first); a content-word exception dictionary
  * the context frame test: for a string of 1-3 ambiguous words between two uniquely coded words, the triple
    (code of the left word, number of ambiguous words, code of the right word) selects the permissible code sequences;
    sequences are intersected, and eliminating a code at one position eliminates its partner in the sequence
  * a sentence begins and ends with a uniquely coded marker

What is NOT in the paper and is mine: the contents of the dictionaries and the suffix list (the paper prints only extracts:
"under 400" function words, "under 1500" exceptions) and the ~500-entry triad table, which the authors derived by hand
from a child's encyclopedia. Here the triad table is generated by rule from a class-adjacency table (ADJACENT below), which
keeps it small and inspectable but is not their table. The test at the bottom measures agreement with the two coded
passages the paper prints (its Tables 2 and 3). The paper itself says its output contained errors and ambiguities.

Run: python3 klein_grammar_coder.py
"""
from __future__ import annotations
import itertools
import re

CLASSES = ["ADJ", "ADV", "NOUN", "VERB", "VERB IS", "AXV", "ART", "CONJC", "CONJR", "CONJRO", "CONJR2", "PREP", "PREP 0", "PREP 1",
           "PREP OF", "PN", "PN S", "PN O", "PN S/O", "PN POS", "PN DEM", "PN REL", "PN IND", "PN RCN", "V/AXV", ". TYPE", ", TYPE",
           "/ED/", "/ING/", "/HAVE/"]
assert len(CLASSES) == 30

FUNCTION = {}
def _f(code, words):
    for w in words.split():
        FUNCTION[w] = {code}
_f("ART", "the a an")
_f("PREP 1", "to")
_f("PREP OF", "of")
_f("PREP 0", "in on at by for from with without about above across after against along among around before behind below beneath beside "
              "between beyond during except inside into near off onto outside over per through throughout toward towards under until "
              "upon within via than_ up_ down_ out_")
_f("CONJC", "and or nor")
_f("CONJR", "but")
_f("CONJR2", "because lest since unless whereas whether while although though if when whenever as than once until_ so_")
_f("VERB IS", "is are was were be been being am isn't")
_f("AXV", "will would shall should may might must ought")
_f("V/AXV", "can could does do did")
_f("/HAVE/", "have has had having")
_f("PN S", "i we he she they who_")
_f("PN O", "me us him them her_")
_f("PN S/O", "it you")
_f("PN POS", "my our his their your its mine ours yours theirs")
_f("PN DEM", "this these those")
_f("PN REL", "that")
_f("PN RCN", "who which what where why whom whose how")
_f("PN IND", "everybody somebody nobody anybody everyone someone anyone everything something nothing anything everywhere somewhere nowhere anywhere")
_f("ADV", "not never too also likewise almost very quite rather often always sometimes soon now then here there thus hence therefore yet still already just only even far_")
_f("ADJ", "no any some many much each every all both few several more most less least other another such")
FUNCTION.pop("than_", None)
FUNCTION = {k.rstrip("_"): v for k, v in FUNCTION.items()}
FUNCTION["her"] = {"PN O", "PN POS"}
FUNCTION["who"] = {"PN RCN"}
FUNCTION["than"] = {"CONJR2"}
FUNCTION["until"] = {"PREP 0", "CONJR2"}
FUNCTION["far"] = {"ADJ", "ADV"}
FUNCTION["as"] = {"CONJR2"}
FUNCTION["that"] = {"PN REL"}
FUNCTION["more"] = {"ADJ"}
FUNCTION["less"] = {"ADJ"}
UNIQUE_FUNCTION = {w for w, c in FUNCTION.items() if len(c) == 1}

EXCEPTIONS = {"swing": {"NOUN", "VERB"}, "speed": {"NOUN", "VERB"}, "strum": {"VERB", "NOUN"}, "means": {"NOUN", "VERB"}, "series": {"NOUN"}, "news": {"NOUN"}}

NOUN_SUFFIX = ("ality", "ation", "ition", "ment", "ness", "ance", "ence", "ity", "ism", "ist", "ship", "tion", "sion", "hood", "dom", "ure", "ics", "ogy", "ery")
ADJ_SUFFIX = ("ical", "ous", "ful", "less", "ive", "able", "ible", "ary", "ish", "ic", "ial", "ian", "ant", "ent", "al", "ar", "oid")
VERB_SUFFIX = ("ize", "ise", "ify", "ate_v")
NOUN_OR_ADJ = ("ate", "ent")
NOUN_OR_VERB = ("l", "le", "li", "er", "or", "y")

TYPE = {".": {". TYPE"}, "?": {". TYPE"}, "!": {". TYPE"}, ":": {". TYPE"}, ",": {", TYPE"}, ";": {", TYPE"}, "--": {", TYPE"}}


def test_dictionary(word, i, n):
    w = word.lower()
    if word in TYPE:
        return TYPE[word]
    if w in FUNCTION:
        return set(FUNCTION[w])
    if w in EXCEPTIONS:
        return set(EXCEPTIONS[w])
    return None


CAPITAL_ALWAYS = False   # True restores the first version: the capital test also hits dictionary words ("The" after a colon -> NONE)


def test_capital(word, i):
    return {"NOUN", "ADJ"} if (word[:1].isupper() and i > 0) else None


def test_numeral(word):
    return {"ADJ"} if re.fullmatch(r"\d+([.,]\d+)?", word) else None


def test_suffix1(word):
    w = word.lower()
    stem = w
    if len(w) > 4 and w.endswith("ing"):
        return {"/ING/"}, w
    if len(w) > 3 and w.endswith("ed") and w not in ("speed", "need", "feed", "seed", "bed", "red", "hundred"):
        return {"/ED/"}, w
    for suf in ("ae",):
        if w.endswith(suf):
            return {"NOUN"}, w
    if w.endswith(("ss", "us")):
        return {"NOUN", "VERB", "ADJ"}, w
    if w.endswith(("is", "as", "um")) and len(w) > 3:
        return {"NOUN"}, w
    if w.endswith("ies") and len(w) > 4:
        return {"NOUN", "VERB"}, w[:-3] + "y"
    if w.endswith("es") and len(w) > 3 and w[-3] in "szhx":
        return {"NOUN", "VERB"}, w[:-2]
    if w.endswith("s") and len(w) > 3:
        return {"NOUN", "VERB"}, w[:-1]
    return None, stem


def test_suffix2(stem):
    for s in sorted(NOUN_SUFFIX, key=len, reverse=True):
        if stem.endswith(s) and len(stem) > len(s) + 1:
            return {"NOUN"}
    for s in sorted(ADJ_SUFFIX, key=len, reverse=True):
        if stem.endswith(s) and len(stem) > len(s) + 1:
            return {"ADJ"}
    for s in ("ize", "ise", "ify"):
        if stem.endswith(s):
            return {"VERB"}
    if stem.endswith("ly") and len(stem) > 4:
        return {"ADV"}
    if stem.endswith("ate") and len(stem) > 5:
        return {"NOUN", "VERB", "ADJ"}
    if stem.endswith(("ful", "ous", "less")):
        return {"ADJ"}
    return None


OPEN = {"NOUN", "VERB", "ADJ"}

# class adjacency (what may immediately follow what), the compact rule that generates the context-frame triads
V_LIKE = {"VERB", "VERB IS", "AXV", "V/AXV", "/HAVE/"}
PREPS = {"PREP", "PREP 0", "PREP 1", "PREP OF"}
CONJ = {"CONJC", "CONJR", "CONJRO", "CONJR2"}
PNS = {"PN", "PN S", "PN O", "PN S/O", "PN POS", "PN DEM", "PN REL", "PN IND", "PN RCN"}
PUNCT = {". TYPE", ", TYPE"}
ADJACENT = {
    "ART": {"ADJ", "NOUN", "/ING/", "/ED/", "ADV"},
    "ADJ": {"ADJ", "NOUN", "/ING/"} | PREPS | CONJ | PUNCT | {"PN REL", "PN RCN"},
    "NOUN": {"NOUN", "ADV", "PN REL", "PN RCN", "/ED/", "/ING/"} | V_LIKE | PREPS | CONJ | PUNCT,
    "VERB": {"ART", "ADJ", "NOUN", "ADV", "/ING/", "/ED/"} | PNS | PREPS | CONJ | PUNCT,
    "VERB IS": {"ART", "ADJ", "NOUN", "ADV", "/ING/", "/ED/"} | PNS | PREPS | CONJ | PUNCT,
    "AXV": {"VERB", "VERB IS", "/HAVE/", "ADV", "/ING/", "/ED/"} | PNS,
    "V/AXV": {"VERB", "VERB IS", "/HAVE/", "ADV", "/ING/", "/ED/", "ART", "ADJ", "NOUN"} | PNS | PUNCT,
    "/HAVE/": {"VERB", "ART", "ADJ", "NOUN", "ADV", "/ED/", "/ING/"} | PNS,
    "/ING/": {"ART", "ADJ", "NOUN", "ADV", "/ED/"} | PNS | PREPS | CONJ | PUNCT,
    "/ED/": {"ART", "ADJ", "NOUN", "ADV", "/ING/"} | PNS | PREPS | CONJ | PUNCT,
    "ADV": {"ADJ", "ADV", "VERB", "VERB IS", "/ED/", "/ING/", "ART", "NOUN"} | PREPS | CONJ | PUNCT | PNS | V_LIKE,
}
for p in PREPS:
    ADJACENT[p] = {"ART", "ADJ", "NOUN", "/ING/", "/ED/", "ADV"} | PNS
for p in CONJ:
    ADJACENT[p] = {"ART", "ADJ", "NOUN", "ADV", "/ING/", "/ED/", "VERB", "VERB IS"} | PNS | PREPS | CONJ
for p in PNS:
    ADJACENT[p] = {"NOUN", "ADJ", "VERB", "VERB IS", "AXV", "V/AXV", "/HAVE/", "ADV", "/ED/", "/ING/", "ART"} | PREPS | CONJ | PUNCT | PNS
for p in PUNCT:
    ADJACENT[p] = {"ART", "ADJ", "NOUN", "ADV", "/ING/", "/ED/", "VERB", "VERB IS"} | PNS | PREPS | CONJ
START = "START"
ADJACENT[START] = {"ART", "ADJ", "NOUN", "ADV", "/ING/", "/ED/", "VERB", "VERB IS", "AXV", "V/AXV"} | PNS | PREPS | CONJ
END_OK = PUNCT | {"NOUN", "ADJ", "ADV", "VERB", "/ED/", "/ING/"}


def triad(left, count, right, candidates):
    """The context frame test: the permissible code sequences between two uniquely coded words. Generated from
    ADJACENT; `candidates` are the per-word code sets coming out of the other tests, and the result is the set of whole
    sequences (tuples) that fit both."""
    out = []
    for seq in itertools.product(*candidates):
        chain = (left,) + seq + (right,)
        if all(b in ADJACENT.get(a, set()) for a, b in zip(chain, chain[1:])):
            out.append(seq)
    return out


def code_sentence(words):
    n = len(words)
    sets = []
    detail = []
    for i, w in enumerate(words):
        outs = []
        d = test_dictionary(w, i, n)
        if d is not None:
            outs.append(d)
        c = test_capital(w, i) if (d is None or CAPITAL_ALWAYS) else None   # a dictionary word stays a function word after ':' or a quote
        if c:
            outs.append(c)
        nm = test_numeral(w)
        if nm:
            outs.append(nm)
        s1 = None
        if d is None:
            s1, stem = test_suffix1(w)
            if s1:
                outs.append(s1)
            s2 = test_suffix2(stem)
            if s2:
                outs.append(s2)
        cur = set(OPEN) if not outs else set.intersection(*outs)         # logical multiplication; no information -> NOUN/VERB/ADJ
        if not cur:
            cur = {"NONE"}
        sets.append(cur)
    # context frame test over maximal runs of ambiguous words bounded by uniquely coded words
    # (the sentence ends are uniquely coded; a missing final period is added as a marker)
    seq_sets = [{START}] + sets + [{". TYPE"} if not (sets and sets[-1] <= PUNCT) else set()]
    seq_sets = [s for s in seq_sets if s]
    i = 0
    while i < len(seq_sets):
        if len(seq_sets[i]) > 1:
            j = i
            while j < len(seq_sets) and len(seq_sets[j]) > 1:
                j += 1
            count = j - i
            if i > 0 and j < len(seq_sets) and count <= 3:
                left = next(iter(seq_sets[i - 1])); right = next(iter(seq_sets[j]))
                sequences = triad(left, count, right, seq_sets[i:j])
                if sequences:
                    for k in range(count):
                        seq_sets[i + k] = {s[k] for s in sequences}
            i = j
        else:
            i += 1
    result = seq_sets[1:1 + n]
    return [sorted(r) for r in result]


def tokenize(text):
    return re.findall(r"[A-Za-z][A-Za-z'-]*|\d+(?:[.,]\d+)?|--|[.,;:?!]", text)


# ===================================== test against the paper's printed Tables 2 and 3 ===============================
TABLE2 = ("Considering that returning space vehicles will be slowed entering the air almost as fast as meteors do , the feasibility of atmospheric deceleration is by no means obvious . "
          "At first glance . Meteors are slowed by the atmosphere , but at rates far beyond the tolerance of any human occupant of a space vehicle .")
TABLE2_CODES = ["/ING/", "PN REL", "/ING/", "NOUN", "NOUN", "AXV", "VERB IS", "/ED/", "/ING/", "ART", "NOUN", "ADV", "CONJR2", "ADJ", "CONJR2", "NOUN", "V/AXV", ", TYPE",
                "ART", "NOUN", "PREP OF", "ADJ", "NOUN", "VERB IS", "PREP 0", "ADJ", "VERB", ["ADJ"], ". TYPE",
                "PREP 0", "ADJ", ["NOUN", "VERB"], ". TYPE", "NOUN", "VERB IS", "/ED/", "PREP 0", "ART", ["NOUN", "ADJ"], ", TYPE", "CONJR", "PREP 0", "NOUN", "ADJ", "PREP 0", "ART", "NOUN",
                "PREP OF", "ADJ", "ADJ", ["ADJ", "NOUN"], "PREP OF", "ART", "NOUN", "NOUN", ". TYPE"]
TABLE3 = ("The blue whale has a massive head and broad snout , and the body tapers gradually to the flukes . "
          "The dorsal fin is falcate and less than a foot long , and is situated at a point a little more than three-fourths the distance from the top of the snout to the notch of the flukes .")
TABLE3_CODES = ["ART", "ADJ", ["ADJ", "NOUN", "VERB"], "/HAVE/", "ART", ["ADJ", "NOUN"], ["NOUN", "VERB"], "CONJC", "ADJ", "NOUN", ", TYPE", "CONJC", "ART", ["ADJ", "NOUN"], ["NOUN", "VERB"], "ADV", "PREP 1", "ART", "NOUN", ". TYPE",
                "ART", "ADJ", "NOUN", "VERB IS", "NOUN", "CONJC", "ADJ", "CONJR2", "ART", "NOUN", "ADJ", ", TYPE", "CONJC", "VERB IS", "/ED/", "PREP 0", "ART", "NOUN", "ART", "ADJ", "ADJ", "CONJR2", "NOUN",
                "ART", "NOUN", "PREP 0", "ART", "NOUN", "PREP OF", "ART", "NOUN", "PREP 1", "ART", "NOUN", "PREP OF", "ART", "NOUN", ". TYPE"]


def compare(text, paper):
    words = tokenize(text)
    mine = code_sentence_text(words)
    rows, agree, unique_ok, uniq_n = [], 0, 0, 0
    for w, m, p in zip(words, mine, paper):
        p = [p] if isinstance(p, str) else p
        same = sorted(p) == sorted(m)
        agree += same
        if len(p) == 1:
            uniq_n += 1
            unique_ok += sorted(p) == sorted(m)
        rows.append((w, m, p, same))
    return rows, agree, len(words), unique_ok, uniq_n


def code_sentence_text(words):
    """Code a text sentence by sentence (a period ends a sentence)."""
    out, cur = [], []
    for w in words:
        cur.append(w)
        if w in (".", "?", "!"):
            out += code_sentence(cur); cur = []
    if cur:
        out += code_sentence(cur)
    return out


def selftest():
    ok = True

    def check(label, cond, extra=""):
        nonlocal ok
        ok &= bool(cond)
        print(f"  [{'PASS' if cond else 'FAIL'}] {label} {extra}")

    check("30 word classes, as in Table 1", len(CLASSES) == 30)
    check("function-word dictionary has under 400 entries", len(FUNCTION) < 400, f"({len(FUNCTION)})")
    # the paper's worked examples
    check("logical multiplication: a word that is NOUN/VERB in one test and VERB/ADJ in another is VERB", {"NOUN", "VERB"} & {"VERB", "ADJ"} == {"VERB"})
    check("a word no test knows allows NOUN, VERB, ADJ (nothing valid is zeroed)", code_sentence(["Zorb", "xyz", "."])[1] != ["NONE"])
    r = code_sentence(["The", "unknownword", "sleeps", "."])
    check("suffix test 1: 'tapers'-type -s words are NOUN or VERB before context", set(code_sentence(["Dogs", "."])[0]) <= {"NOUN", "VERB", "ADJ"})
    check("capitalization test: a non-initial capital word is NOUN/ADJ", test_capital("Meteors", 3) == {"NOUN", "ADJ"})
    check("the paper's own triad example: ART [ADJ NOUN | NOUN ADV | NOUN NOUN] VERB leaves ADJ NOUN (3.2.4)",
          triad("ART", 2, "VERB", [{"ADJ", "NOUN"}, {"VERB", "ADJ", "NOUN"}]) and ("ADJ", "NOUN") in triad("ART", 2, "VERB", [{"ADJ", "NOUN"}, {"VERB", "ADJ", "NOUN"}]))
    print("  [info] the paper's ART N V example: sequences found between ART and VERB with 2 ambiguous words:", triad("ART", 2, "VERB", [{"ADJ", "NOUN"}, {"ADJ", "NOUN", "ADV"}]))
    # agreement with the paper's printed Tables 2 and 3
    for name, text, paper in (("Table 2 (Scientific American)", TABLE2, TABLE2_CODES), ("Table 3 (Encyclopedia Americana)", TABLE3, TABLE3_CODES)):
        words = tokenize(text)
        if len(words) != len(paper):
            print(f"  [info] {name}: {len(words)} words vs {len(paper)} codes printed in my transcription; compared on the first {min(len(words), len(paper))}")
        rows, agree, n, uok, un = compare(text, paper[:len(tokenize(text))] if len(paper) >= len(tokenize(text)) else paper + ["?"] * (len(tokenize(text)) - len(paper)))
        print(f"  [measure] {name}: same code set as the paper on {agree}/{n} words; where the paper printed ONE code: {uok}/{un}")
        TABLE_ROWS[name] = rows
    print("ALL PASS" if ok else "SOME FAILED")
    return ok


TABLE_ROWS = {}

if __name__ == "__main__":
    ok = selftest()
    for name, rows in TABLE_ROWS.items():
        print(f"\n--- {name}: word | mine | paper")
        for w, m, p, same in rows:
            print(f"  {'=' if same else 'x'} {w:14s} {','.join(m):26s} {','.join(p)}")
    raise SystemExit(0 if ok else 1)
